#include <bits/stdc++.h>
using namespace std;

vector<int> findOrder(int n, const vector<pair<int,int>>& pairs) {
    vector<vector<int>> g(n);
    vector<int> indeg(n, 0);
    for (auto &e : pairs) {
        int a = e.first, b = e.second;   // b -> a
        if (0 <= a && a < n && 0 <= b && b < n) {
            g[b].push_back(a);
            indeg[a]++;
        }
    }

    // 小根堆
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) pq.push(i);
    }

    vector<int> order;
    order.reserve(n);
    while (!pq.empty()) {
        int u = pq.top(); pq.pop();
        order.push_back(u);
        for (int v : g[u]) {
            if (--indeg[v] == 0) {
                pq.push(v);
            }
        }
    }

    if ((int)order.size() < n) return {}; // 有环，无解
    return order;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 读取全部输入
